insert into public.services (business_id, category_id, slug, name, short_description, full_description, price_cents, starting_price, duration_minutes, deposit_cents, benefits, preparation, maintenance_interval_days, seo, featured, bookable, content_status, active, sort_order) values ((select id from public.businesses where slug='luxury-barber-lounge'), (select id from public.service_categories where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug='haircuts-fades'), 'signature-haircut', '{"en":"Signature Haircut","es":"Corte Signature"}'::jsonb, '{"en":"Consultation, precision cut, rinse, styling, and a finish built for your routine.","es":"Consulta, corte de precisión, enjuague, peinado y acabado para tu rutina."}'::jsonb, '{"en":"A tailored haircut built around head shape, growth pattern, texture, and daily styling. The service includes a clear consultation, precision cutting, detailed neckline and perimeter work, and product guidance.","es":"Un corte personalizado según la forma de la cabeza, crecimiento, textura y rutina diaria. Incluye consulta, corte de precisión, detalles del contorno y guía de productos."}'::jsonb, 4500, true, 45, 1500, '[{"en":"Personal consultation before the service begins","es":"Consulta personal antes de comenzar"},{"en":"Detailed finishing and styling guidance","es":"Acabado detallado y guía de estilo"}]'::jsonb, '{"en":"Arrive with your hair in its normal condition and bring any reference images that clarify the result you want.","es":"Llega con el cabello en su condición normal y trae imágenes de referencia que aclaren el resultado que deseas."}'::jsonb, 21, '{"title":"Signature Haircut","description":"Consultation, precision cut, rinse, styling, and a finish built for your routine.","tags":["haircut","custom cut","scissor cut"]}'::jsonb, true, true, 'published', true, 0) on conflict (business_id, slug) do update set category_id=excluded.category_id, name=excluded.name, short_description=excluded.short_description, full_description=excluded.full_description, price_cents=excluded.price_cents, duration_minutes=excluded.duration_minutes, deposit_cents=excluded.deposit_cents, benefits=excluded.benefits, preparation=excluded.preparation, seo=excluded.seo, featured=excluded.featured, content_status=excluded.content_status, active=true, sort_order=excluded.sort_order;
insert into public.services (business_id, category_id, slug, name, short_description, full_description, price_cents, starting_price, duration_minutes, deposit_cents, benefits, preparation, maintenance_interval_days, seo, featured, bookable, content_status, active, sort_order) values ((select id from public.businesses where slug='luxury-barber-lounge'), (select id from public.service_categories where business_id=(select id from public.businesses where slug='luxury-barber-lounge') and slug='haircuts-fades'), 'fade-cut', '{"en":"Fade Cut","es":"Corte Fade"}'::jsonb, '{"en":"A clean gradient with deliberate weight, crisp edges, and balanced shape.","es":"Un degradado limpio con peso deliberado, bordes precisos y forma equilibrada."}'::jsonb, '{"en":"Choose low, mid, high, taper, or skin fade. Your barber balances the fade with the top length and finishes the perimeter with exact detailing.","es":"Elige fade bajo, medio, alto, taper o skin fade. El barbero equilibra el degradado con la parte superior y termina el contorno con precisión."}'::jsonb, 4500, true, 45, 1500, '[{"en":"Personal consultation before the service begins","es":"Consulta personal antes de comenzar"},{"en":"Detailed finishing and styling guidance","es":"Acabado detallado y guía de estilo"}]'::jsonb, '{"en":"Arrive with your hair in its normal condition and bring any reference images that clarify the result you want.","es":"Llega con el cabello en su condición normal y trae imágenes de referencia que aclaren el resultado que deseas."}'::jsonb, 21, '{"title":"Fade Cut","description":"A clean gradient with deliberate weight, crisp edges, and balanced shape.","tags":["fade","skin fade","taper"]}'::jsonb, true, true, 'published', true, 10) on conflict (business_id, slug) do update set category_id=excluded.category_id, name=excluded.name, short_description=excluded.short_description, full_description=excluded.full_description, price_cents=excluded.price_cents, duration_minutes=excluded.duration_minutes, depo