insert into public.barber_profiles (business_id, slug, display_name, professional_title, short_intro, biography, story, specialties, languages, social_links, square_team_member_id, featured, active, demo, status, sort_order) values ((select id from public.businesses where slug='luxury-barber-lounge'), 'adrian-cole', 'Adrian Cole', '{"en":"Senior Barber","es":"Barbero Senior"}'::jsonb, '{"en":"A calm, exacting barber with an eye for tailored silhouettes, clean transitions, and balanced beard structure.","es":"Barbero sereno y preciso con enfoque en siluetas personalizadas, transiciones limpias y barba equilibrada."}'::jsonb, '{"en":"A calm, exacting barber with an eye for tailored silhouettes, clean transitions, and balanced beard structure.","es":"Barbero sereno y preciso con enfoque en siluetas personalizadas, transiciones limpias y barba equilibrada."}'::jsonb, '{"en":"Adrian works from the complete silhouette backward, balancing structure and softness so each service suits the client beyond the chair.","es":"Adrian parte de la silueta completa, equilibrando estructura y suavidad para que cada servicio se adapte al cliente."}'::jsonb, '["signature-haircut","beard-trim","hot-towel-shave"]'::jsonb, array['en']::text[], '{}'::jsonb, null, true, true, true, 'published', 3) on conflict (business_id, slug) do update set display_name=excluded.display_name, professional_title=excluded.professional_title, short_intro=excluded.short_intro, biography=excluded.biography, story=excluded.story, specialties=excluded.specialties, languages=excluded.languages, social_links=excluded.social_links, square_team_member_id=excluded.square_team_member_id, featured=excluded.featured, active=excluded.active, demo=excluded.demo, status=excluded.status, sort_order=excluded.sort_order;
