insert into public.barber_profiles (business_id, slug, display_name, professional_title, short_intro, biography, story, specialties, languages, social_links, square_team_member_id, featured, active, demo, status, sort_order) values ((select id from public.businesses where slug='luxury-barber-lounge'), 'julian-vega', 'Julian Vega', '{"en":"Precision Barber","es":"Barbero de Precisión"}'::jsonb, '{"en":"A technical barber balancing crisp clipper work with natural texture and understated finishing.","es":"Barbero técnico que equilibra máquina precisa, textura natural y acabado sobrio."}'::jsonb, '{"en":"A technical barber balancing crisp clipper work with natural texture and understated finishing.","es":"Barbero técnico que equilibra máquina precisa, textura natural y acabado sobrio."}'::jsonb, '{"en":"Julian builds clean structure first, then softens the finish where needed so the result reads polished rather than overworked.","es":"Julian construye una estructura limpia y suaviza el acabado donde corresponde para un resultado pulido."}'::jsonb, '["fade-cut","razor-cut","hair-shape-up"]'::jsonb, array['en','es']::text[], '{}'::jsonb, null, false, true, true, 'published', 5) on conflict (business_id, slug) do update set display_name=excluded.display_name, professional_title=excluded.professional_title, short_intro=excluded.short_intro, biography=excluded.biography, story=excluded.story, specialties=excluded.specialties, languages=excluded.languages, social_links=excluded.social_links, square_team_member_id=excluded.square_team_member_id, featured=excluded.featured, active=excluded.active, demo=excluded.demo, status=excluded.status, sort_order=excluded.sort_order;
